                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["CONNECTION_ERROR"] = traceback.format_exc()
    return name, results

def collect_host(name, params):
    results = {}
    try:
        conn = ConnectHandler(**params)
        cmds = [
            "ip addr show",
            "ip route show",
            "cat /etc/network/interfaces",
        ]
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=15)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["CONNECTION_ERROR"] = traceback.format_exc()
    return name, results

